    note: "■ 這間是什麼\n港區白金、1999年新耐震基準的7層大樓，6樓的1LDK，2026年7月完成全室翻新。原始建商（分譲）是三井物產、施工長谷工，適合想住在港區高級住宅區的單身族或兩人家庭，也很適合當都心的第二個家。\n■ 亮點\n<b>白金高輪站徒步7分的港區白金地址</b>：南北線、三田線直通六本木一丁目、大手町方向，白金台、廣尾也在步行範圍。附近有24小時營業的超市，周邊「白金一丁目西部中地區」再開發預計2030年完工，生活機能還會再升級。\n■ 格局與設備\n客廳與臥室都面向陽台的寬面寬格局，陽台前方與對面建築之間有空間，採光好。LDK約9.5帖並新設地暖，臥室約4.0帖以拉門跟客廳相連。收納與洗臉室裝了可調層板，設備有洗碗機、淨水器、浴室乾燥機、追焚保溫浴缸。\n■ 管理與生活\n全部委託管理、管理員通勤，有附螢幕的自動門鎖、宅配櫃與防犯攝影機，有長期修繕計畫，可養寵物（依規約）。交屋時間可以跟賣方討論，我來幫你協調。\n■ 想看房或試算貸款\n照片中的家具是佈置用，不含在售價內。屋齡二十多年的物件，各家銀行的看法不太一樣，我可以先幫你問過幾家再決定怎麼出手。能不能貸、可貸成數依銀行審查為準。稅額請由稅理士確認，登記與契約由司法書士・宅建士確認。想看房或想試算月付，加LINE跟我說一聲就好。"
