    note: "■ 這是什麼\n大田區山王、JR京濱東北線「大森」站徒步<b>3分</b>的<b>買地自建・訂製住宅用地</b>（日文叫「建築條件付売地」），是我們自社的案子，A・B・C 三個區畫一次釋出。現況為空地（更地），2026年11月上旬交地預定。\n■ 亮點：第一種低層＋走路3分\n山手線一站到品川、兩站到東京，走路三分鐘就到大森站，卻是<b>第一種低層住居專用地域</b>——周邊不會蓋起高樓或商業設施，日照與寧靜度有法規在保障。學區是區立山王小學校徒步2分。這個組合在大森不常出現。\n■ 三個區畫\nA區畫 95.46㎡／土地 1億4,990万円・建物參考 3,990万円\nB區畫 99.94㎡／土地 1億6,990万円・建物參考 4,990万円——土地最大、而且是唯一直接面路的一塊，參考方案排得進內建車庫\nC區畫 96.01㎡／土地 1億4,990万円・建物參考 3,990万円\n三區都是3層建的參考方案，也都附步入式衣帽間。\n■ 規則我先講清楚\n建築條件付的意思是<b>房子由我們公司承建</b>，要在一定期間內簽好建築工程契約；沒談成的話土地契約一併解除、款項退還。A、C兩區由通道連到前面道路（敷地延長），B直接面路；前面道路是法42條2項道路，面寬約4.0m是退縮後的數字。這種地形各家銀行的估價差很多，我可以先幫你問過幾家再決定怎麼出手。\n■ 想在東京蓋自己的家\n買地自建的流程、付款節奏、貸款時點都跟買現成的不一樣，外國人更要提早抓。加LINE跟我說一聲，我用中文從選地、設計到交屋一路陪你走完（相簿第一張是<b>參考外觀示意圖</b>，不是完成預想圖、也不是任何一區的定案設計；平面圖與區劃圖同樣是參考方案；建物參考價格會隨最後決定的設計與規格變動）。"
