    note: "■ 這是未公開的獨家物件\n這間沒有登在 REINS（日本不動產流通標準情報系統），也不會出現在一般入口網站上，是周周這邊才拿得到的物件。有興趣的話請直接跟我聯絡。\n■ 上野毛是什麼樣的地方\n世田谷區上野毛一帶是東京數一數二安靜的高級住宅區，第一種低層住居專用地域，路上幾乎沒有高樓，整條街都是獨棟。五島美術館、多摩川的河岸綠地都在生活圈裡，環境非常成熟。\n■ 土地136坪、RC造\n土地449.58㎡（約136坪）、建物276.34㎡。RC造二層建，可停4台車。在世田谷這個位置能有136坪的土地，本身就是稀有度很高的條件——土地價值是這間物件的核心。\n■ 翻新工程進行中\n預定實施全新的內外裝工程，工程完工預定日是2026年9月4日。也就是說你買到的會是整理過的狀態，不用自己再發包一次。相簿目前只有外觀與平面圖，內部完成後的照片我會再補上；想先看現場也可以安排。\n■ 周周的看法\n這個價格帶的買方通常在意兩件事：地段會不會保值、將來好不好處理。上野毛的低層住宅區在世田谷屬於長期穩定的類型，土地大、臨路條件好，未來要自用、要重建、要轉手都有彈性。\n因為是未公開物件，資料我不會全部放在網路上——想看詳細圖面、確認工程內容或安排現場，加LINE跟周周說一聲。"
